function clip(text: string): string {
  if (text.length <= LOG_LIMIT) return text
  return `${text.slice(0, LOG_LIMIT)}\n…truncated (${text.length} chars)`
}

function fail(message: string) {
  return {
    content: [{ type: 'text' as const, text: message }],
    isError: true,
  }
}

function ok(text: string) {
  return {
    content: [{ type: 'text' as const, text }],
  }
}

function withId(text: string, sandbox: Sandbox) {
  return ok(`${text}\n\nsandbox_id=${sandbox.sandboxId}`)
}

export const mcpHandler = createMcpHandler(
  server => {
    server.registerTool(
      'create',
      {
        title: 'Create sandbox',
        description:
          'Call this first in a conversation. Creates a new sandbox and returns sandbox_id plus environment notes. Then pass that sandbox_id to every other Cloudlets tool.',
        inputSchema: z.object({}),
      },
      async () => {
        try {
          const sandbox = await createSandbox()
          return ok(
            [
              `sandbox_id=${sandbox.sandboxId}`,
              'Pass this sandbox_id on every later write_file, read_file, run, and preview_url call. If you skip create or invent an id, those tools will fail.',
              '',
              CREATE_NOTES,
            ].join('\n'),
          )
        } catch (error) {
          return fail(formatCommandError(error))
        }
      },
    )

    server.registerTool(
      'write_file',
      {
        title: 'Write file',
        description: `Write a file in the sandbox. Call create first. Relative paths go under ${WORKSPACE}. Parent directories are created.`,
        inputSchema: z.object({
          sandbox_id: sandboxIdField,
          path: z.string().min(1),
          content: z.string(),
        }),
      },
      async ({ path, content, sandbox_id }) => {
        try {
          const sandbox = await getSandbox(sandbox_id)
          const full = resolvePath(path)
          await sandbox.files.write(full, content)
          return withId(`wrote ${full}`, sandbox)
        } catch (error) {
          return fail(formatCommandError(error))
        }
      },
    )

    server.registerTool(
      'read_file',
      {
        title: 'Read file',
        description: `Read a file from the sandbox. Call create first. Relative paths go under ${WORKSPACE}.`,
        inputSchema: z.object({
          sandbox_id: sandboxIdField,
          path: z.string().min(1),
        }),
      },
      async ({ path, sandbox_id }) => {
        try {
          const sandbox = await getSandbox(sandbox_id)
          const full = resolvePath(path)
          const content = await sandbox.files.read(full)
          return withId(clip(content), sandbox)
        } catch (error) {
          return fail(formatCommandError(error))
        }
      },
    )

    server.registerTool(
      'run',
      {
        title: 'Run command',
        description: `Run a shell command in ${WORKSPACE}. Call create first. Use background=true for long-lived processes such as a dev server. Background returns only a pid; redirect to a log if you need boot output. Foreground commands time out after 90 seconds. stdout and stderr are always returned as labelled fields.`,
        inputSchema: z.object({
          sandbox_id: sandboxIdField,
          command: z.string().min(1),
          background: z.boolean().optional(),
        }),
      },
      async ({ command, background, sandbox_id }) => {
        try {
          const sandbox = await getSandbox(sandbox_id)
          if (background) {
            const handle = await sandbox.commands.run(command, {
              cwd: WORKSPACE,
              background: true,
            })
            return withId(`started in background, pid ${handle.pid}`, sandbox)
          }

          const result = await sandbox.commands.run(command, {
            cwd: WORKSPACE,
            timeoutMs: RUN_TIMEOUT_MS,
          })
          const parts = [
            `exit ${result.exitCode}`,
            `stdout:\n${result.stdout ? clip(result.stdout) : '(empty)'}`,
            `stderr:\n${result.stderr ? clip(result.stderr) : '(empty)'}`,
          ]
          const text = parts.join('\n\n')
          return result.exitCode === 0
            ? withId(text, sandbox)
            : fail(`${text}\n\nsandbox_id=${sandbox.sandboxId}`)
        } catch (error) {
          return fail(formatCommandError(error))
        }
      },
    )

    server.registerTool(
      'preview_url',
      {
        title: 'Preview URL',
        description:
          'Public HTTPS URL for a port already listening inside the sandbox. Call create first, then start the server with run(background=true). Vite 5.4.12+ and some Next dev servers reject unknown Host headers; set server.allowedHosts to true or the preview URL 403s while the process is still up.',
        inputSchema: z.object({
          sandbox_id: sandboxIdField,
          port: z.number().int().min(1).max(65535).default(3000),
        }),
      },
      async ({ port, sandbox_id }) => {
        try {
          const sandbox = await getSandbox(sandbox_id)
          const host = sandbox.getHost(port)
          const url = host.startsWith('http') ? host : `https://${host}`
          return withId(
            `${url}\nIf this is a paused box, the first hit may take a second to wake.`,
            sandbox,
          )
        } catch (error) {
          return fail(formatCommandError(error))
        }
      },
    )
  },
  {
    serverInfo: {
      name: 'cloudlets',
      version: '0.1.0',
    },
    instructions: [
      'Call create first. It returns sandbox_id and environment notes.',
      'Pass that sandbox_id to every later write_file, read_file, run, and preview_url call. Those tools require it and will not create a box.',
      'If you already have a sandbox_id from this conversation, skip create and reuse it.',
    ].join(' '),
  },
)
